import re
def gtid_kind(s):
    if re.fullmatch(r"[0-9a-fA-F-]{36}:\d+(-\d+)?(:\d+(-\d+)?)*", s):
        return "MySQL (서버 UUID:번호 구간)"
    if re.fullmatch(r"\d+-\d+-\d+", s):
        return "MariaDB (도메인-서버id-번호)"
    return "모름"
for g in ["3E11FA47-71CA-11E1-9E33-C80AA9429562:1-5", "0-101-2048", "101:2048"]:
    print(f"{g:42s} → {gtid_kind(g)}")

# 3E11FA47-71CA-11E1-9E33-C80AA9429562:1-5   → MySQL (서버 UUID:번호 구간)
# 0-101-2048                                 → MariaDB (도메인-서버id-번호)
# 101:2048                                   → 모름
